# Sequential linearization method (SLM) on the dual PEP NSDP, after
# Kamri, Hendrickx & Glineur, "Numerical design of optimized first-order
# algorithms" (2025), with two extensions used in the paper:
#   • policies: the step sizes are generated by η(ω); the LMI is linearized
#     through the Jacobian J = ∂η/∂ω (prior on the step sizes);
#   • second order (SQP-TR): the tangent objective is augmented with
#     ½ Δωᵀ B Δω, where B is the PSD part of the ωω-block of the NSDP
#     Lagrangian Hessian (the pulled-back frozen-certificate curvature).
#
# Dual NSDP of the compiled PEP (pieces C_k of a max-min objective, γ ∈ Δ):
#   min_{λ,γ,ω}  Σ_k γ_k c0_k − Σ_c λ_c c0_c
#   s.t.  S = Σ_c λ_c A_c(η(ω)) − Σ_k γ_k C_k(η(ω)) ⪰ 0
#         Σ_k γ_k f_k − Σ_c λ_c f_c = 0,  λ_c ≥ 0 (c ∈ ≤),  γ ≥ 0, Σγ = 1.
# Each iteration solves one tangent SDP (LMI linearized at the current PEP
# duals, trust region ‖(Δω, Δλ_TR, Δγ)‖₂ ≤ Δ) and one PEP at the trial point;
# the trial duals become the next linearization point when accepted.
# Kamri's trust-region rule: ρ = ΔW / pred; ρ ≥ 0.9 → accept, Δ ← 2Δ;
# ρ ≤ 0.1 → reject, Δ ← Δ/2; otherwise accept.

# Dense symmetric accumulation of w·S for sparse S.
function _axpy_sparse!(K::Matrix{Float64}, w::Float64, S::SpMat)
    rows = rowvals(S)
    vals = nonzeros(S)
    for j in 1:size(S, 2), k in nzrange(S, j)
        K[rows[k], j] += w * vals[k]
    end
    return K
end

# K_r = ∂S/∂η_r = Σ_c λ_c ∂A_c/∂η_r − Σ_k γ_k ∂C_k/∂η_r at η.
function _dual_direction_kernels(cp::CompiledPEP, η::AbstractVector{<:Real},
                                 λ::Vector{Float64}, γ::Vector{Float64})
    K = Dict{Int,Matrix{Float64}}()
    add!(r, w, S) = _axpy_sparse!(get!(() -> zeros(cp.dim, cp.dim), K, r), w, S)
    function acc!(M::ParamMatrix, w::Float64)
        w == 0.0 && return
        for (r, S) in M.A1
            add!(r, w, S)
        end
        for (r, s, S) in M.A2
            if r == s
                add!(r, 2.0 * w * η[r], S)
            else
                add!(r, w * η[s], S)
                add!(s, w * η[r], S)
            end
        end
    end
    for (c, con) in enumerate(cp.cons)
        acc!(con.expr.M, λ[c])
    end
    for (k, piece) in enumerate(cp.obj)
        acc!(piece.M, -γ[k])
    end
    return K
end

# Projected (sign-feasible) dual multipliers of a PEP solution.
function _clean_duals(cp::CompiledPEP, sol::PEPSolution)
    λ = copy(sol.duals)
    for (c, con) in enumerate(cp.cons)
        con.sense == :le && (λ[c] = max(λ[c], 0.0))
    end
    γ = max.(copy(sol.obj_duals), 0.0)
    sγ = sum(γ)
    γ = sγ > 0 ? γ ./ sγ : fill(1.0 / length(γ), length(γ))
    return λ, γ
end

"""
    SLMTangent

Linearized dual block of one PEP inside a tangent model: `dobj` is the
linearized change of the dual objective (the predicted change of W) and
`trvars` the multiplier increments entering the trust-region norm.
"""
struct SLMTangent
    dobj::AffExpr
    trvars::Vector{VariableRef}
end

"""
    add_slm_tangent!(model, dp, ω, sol, dω; tr_exclude_objective=true) :: SLMTangent

Add the linearization of the dual PEP of `dp` at `(ω, sol)` to `model`,
sharing the design increment variables `dω`. Multipliers of constraints with
a nonzero constant term (e.g. the initial condition, Kamri's τ) are left out
of the trust region when `tr_exclude_objective` (Kamri's convention).
"""
function add_slm_tangent!(model::Model, dp::DesignProblem, ω::AbstractVector{<:Real},
                          sol::PEPSolution, dω::Vector{VariableRef};
                          tr_exclude_objective::Bool = true)
    cp = dp.cp
    isempty(cp.psd) ||
        error("design_slm does not yet support PEPs with PSD (LMI) blocks")
    nc = length(cp.cons)
    npc = length(cp.obj)
    η, J, _ = evaluate_policy(dp.policy, ω, dp.N)
    λ, γ = _clean_duals(cp, sol)

    Acs = [assemble(con.expr.M, η) for con in cp.cons]
    Cks = [assemble(piece.M, η) for piece in cp.obj]
    S = zeros(cp.dim, cp.dim)
    for c in 1:nc
        λ[c] == 0.0 || _axpy_sparse!(S, λ[c], Acs[c])
    end
    for k in 1:npc
        _axpy_sparse!(S, -γ[k], Cks[k])
    end
    K = _dual_direction_kernels(cp, η, λ, γ)
    κ = length(dω)
    Mdir = Vector{Matrix{Float64}}(undef, κ)
    for ν in 1:κ
        Mν = zeros(cp.dim, cp.dim)
        for (r, Kr) in K
            J[r, ν] == 0.0 || (Mν .+= J[r, ν] .* Kr)
        end
        Mdir[ν] = Mν
    end

    dλ = @variable(model, [1:nc])
    dγ = npc > 1 ? @variable(model, [1:npc]) : VariableRef[]

    # LMI: S + Σ dλ_c A_c − Σ dγ_k C_k + Σ dω_ν M_ν ⪰ 0 (upper triangle)
    n = cp.dim
    mat = Matrix{AffExpr}(undef, n, n)
    for j in 1:n, i in 1:j
        mat[i, j] = AffExpr(S[i, j])
    end
    function addsparse!(Sm::SpMat, v::VariableRef, w::Float64)
        rows = rowvals(Sm)
        vals = nonzeros(Sm)
        for j in 1:n, k in nzrange(Sm, j)
            i = rows[k]
            i <= j && add_to_expression!(mat[i, j], w * vals[k], v)
        end
    end
    for c in 1:nc
        addsparse!(Acs[c], dλ[c], 1.0)
    end
    for k in 1:length(dγ)
        addsparse!(Cks[k], dγ[k], -1.0)
    end
    for ν in 1:κ
        Mν = Mdir[ν]
        for j in 1:n, i in 1:j
            Mν[i, j] == 0.0 || add_to_expression!(mat[i, j], Mν[i, j], dω[ν])
        end
    end
    for j in 1:n, i in (j + 1):n
        mat[i, j] = mat[j, i]
    end
    @constraint(model, Symmetric(mat) in PSDCone())

    # Function-value stationarity (linear in the multipliers, kept exact)
    for q in 1:cp.nf
        h = sum(γ[k] * cp.obj[k].f[q] for k in 1:npc) -
            sum(λ[c] * cp.cons[c].expr.f[q] for c in 1:nc)
        ex = AffExpr(h)
        for c in 1:nc
            fq = cp.cons[c].expr.f[q]
            fq == 0.0 || add_to_expression!(ex, -fq, dλ[c])
        end
        for k in 1:length(dγ)
            fq = cp.obj[k].f[q]
            fq == 0.0 || add_to_expression!(ex, fq, dγ[k])
        end
        isempty(ex.terms) && abs(h) < 1e-12 && continue
        @constraint(model, ex == 0)
    end
    for c in 1:nc
        cp.cons[c].sense == :le && @constraint(model, λ[c] + dλ[c] >= 0)
    end
    if npc > 1
        @constraint(model, γ .+ dγ .>= 0)
        @constraint(model, sum(dγ) == 0)
    end

    dobj = AffExpr(0.0)
    for c in 1:nc
        c0 = cp.cons[c].expr.c0
        c0 == 0.0 || add_to_expression!(dobj, -c0, dλ[c])
    end
    for k in 1:length(dγ)
        c0 = cp.obj[k].c0
        c0 == 0.0 || add_to_expression!(dobj, c0, dγ[k])
    end
    trvars = VariableRef[dλ[c] for c in 1:nc
                         if !(tr_exclude_objective && cp.cons[c].expr.c0 != 0.0)]
    append!(trvars, dγ)
    return SLMTangent(dobj, trvars)
end

# PSD part of a symmetric matrix and a factor U with UᵀU = B.
function _psd_factor(H::AbstractMatrix{Float64}; floor::Float64 = 0.0)
    E = eigen(Symmetric((H + H') / 2))
    keep = findall(>(floor), E.values)
    isempty(keep) && return zeros(0, size(H, 1))
    return Diagonal(sqrt.(E.values[keep])) * E.vectors[:, keep]'
end

# Powell-damped BFGS update of B (kept PD) from step s and gradient change y.
# The first update initializes B = (yᵀy / sᵀy) I (or skips if sᵀy ≤ 0).
# Returns whether B is initialized.
function _damped_bfgs!(B::Matrix{Float64}, s::Vector{Float64},
                       y::Vector{Float64}, initialized::Bool)
    sy = dot(s, y)
    ss = dot(s, s)
    ss <= 1e-20 && return initialized
    if !initialized
        sy <= 1e-12 * ss && return false
        B .= (dot(y, y) / sy) .* Matrix{Float64}(LinearAlgebra.I, length(s), length(s))
    end
    Bs = B * s
    sBs = dot(s, Bs)
    sBs <= 1e-20 && return true
    θ = sy >= 0.2 * sBs ? 1.0 : 0.8 * sBs / (sBs - sy)
    r = θ .* y .+ (1 - θ) .* Bs
    B .+= (r * r') ./ dot(s, r) .- (Bs * Bs') ./ sBs
    B .= (B .+ B') ./ 2
    return true
end

# Safe PEP evaluation: (W, sol) or (Inf, nothing) on solver failure.
function _safe_pep(dp::DesignProblem, ω; require_certified::Bool = false)
    try
        W, sol, _ = pep_value(dp, ω)
        if !isfinite(W) || (require_certified && !sol.diagnostics.certified)
            @warn "SLM rejected an invalid PEP evaluation" W status = sol.status diagnostics = sol.diagnostics
            return Inf, nothing
        end
        return W, sol
    catch err
        err isa InterruptException && rethrow()
        @warn "SLM PEP evaluation failed" exception = (err, catch_backtrace())
        return Inf, nothing
    end
end

"""
    design_slm(dp, ω0; iters=1000, Δ0=100.0, hessian=:none, ρ_good=0.9,
               ρ_bad=0.1, tolW=1e-7, tolstep=1e-4, Δmin=1e-10,
               tr_exclude_objective=true, max_time=Inf, stats=nothing,
               require_certified=false, verbose=false) :: DesignTrace

Sequential linearization (Kamri's SLM) on the dual PEP NSDP, in the policy
space of `dp` (`IdentityPolicy` = Kamri's free step sizes).

`hessian = :none` is Kamri's first-order method; `hessian = :cert` adds the
second-order model term ½ΔωᵀBΔω with B the PSD part of the pulled-back
frozen-certificate curvature (SQP-TR); `hessian = :bfgs` uses a
Powell-damped BFGS approximation of the reduced Hessian built from the exact
envelope gradients at accepted points (no extra SDP solves). Note that B = 0
under `:cert` whenever the constraint matrices are affine in η (e.g. smooth
convex GD) or the frozen curvature is negative definite (residual
encodings), in which case `:cert` coincides with `:none`. Stopping follows Kamri:
|ΔW| ≤ `tolW` and ‖Δω‖ < `tolstep`, or Δ < `Δmin`, `iters`, or `max_time`.

Budget: each iteration costs one tangent SDP and one PEP solve; `solves_hist`
counts PEP solves and `tangent_hist` tangent SDPs. Optional `stats::Dict`
receives the trust-radius, ratio, and acceptance histories, tangent termination
statuses, and separate model-build, tangent-solve, and trial-PEP timings.
Set `require_certified=true` to reject PEP values that fail the numerical
certificate checks, including at initialization. Defaults to false for
compatibility; use true for measured best-so-far comparisons.
"""
function design_slm(dp::DesignProblem, ω0::AbstractVector{<:Real};
                    iters::Int = 1000, Δ0::Float64 = 100.0,
                    hessian::Symbol = :none, hess_floor::Float64 = 0.0,
                    ρ_good::Float64 = 0.9, ρ_bad::Float64 = 0.1,
                    tolW::Float64 = 1e-7, tolstep::Float64 = 1e-4,
                    Δmin::Float64 = 1e-10, tr_exclude_objective::Bool = true,
                    max_time::Float64 = Inf,
                    stats::Union{Nothing,Dict{Symbol,Any}} = nothing,
                    require_certified::Bool = false,
                    verbose::Bool = false)
    dp.facial_reduction == :none ||
        error("design_slm requires dual multipliers; facial reduction is unsupported")
    hessian in (:none, :cert, :bfgs) ||
        error("unknown hessian mode :$hessian (use :none, :cert or :bfgs)")
    t0 = time()
    κ = length(ω0)
    ω = collect(Float64, ω0)
    t_initial_pep = time()
    W, sol = _safe_pep(dp, ω; require_certified)
    initial_pep_time = time() - t_initial_pep
    sol === nothing && error("design_slm: PEP solve failed at the initial point")
    npep = 1
    ntan = 0
    Δ = Δ0
    gradω(ωx, solx) = begin
        ηx, _, _ = evaluate_policy(dp.policy, ωx, dp.N)
        pep_grad_hess(dp, ωx, ηx, solx; hess = false)[1]
    end
    g = hessian == :bfgs ? gradω(ω, sol) : Float64[]
    B = zeros(κ, κ)
    B_init = false

    ω_hist = [copy(ω)]
    values = [W]
    solves_hist = [npep]
    tangent_hist = [ntan]
    time_hist = [time() - t0]
    Δ_hist = Float64[]
    ρ_hist = Float64[]
    acc_hist = Bool[]
    tangent_build_time = Float64[]
    tangent_solve_time = Float64[]
    trial_pep_time = Float64[]
    tangent_status = String[]

    for it in 1:iters
        time() - t0 > max_time && break
        t_tangent_build = time()
        model = _make_model(dp.backend)
        dω = @variable(model, [1:κ])
        blk = add_slm_tangent!(model, dp, ω, sol, dω; tr_exclude_objective)
        @variable(model, s)
        @constraint(model, [s; dω; blk.trvars] in SecondOrderCone())
        @constraint(model, s <= Δ)
        obj = blk.dobj
        U = zeros(0, κ)
        if hessian == :cert
            η, J, Hpol = evaluate_policy(dp.policy, ω, dp.N)
            gη, Hη = grad_hess_eta(dp.cp, η, sol)
            _, Hω = pullback(gη, Hη, J, Hpol)
            U = _psd_factor(Hω; floor = hess_floor)
        elseif hessian == :bfgs && B_init
            U = _psd_factor(B; floor = hess_floor)
        end
        if size(U, 1) > 0
            @variable(model, q >= 0)
            @constraint(model, [q; 1.0; U * dω] in RotatedSecondOrderCone())
            obj = obj + q                           # q ≥ ½‖U dω‖² = ½ dωᵀBdω
        end
        @objective(model, Min, obj)
        build_elapsed = time() - t_tangent_build
        t_tangent_solve = time()
        optimize!(model)
        solve_elapsed = time() - t_tangent_solve
        ntan += 1
        st = termination_status(model)
        push!(tangent_build_time, build_elapsed)
        push!(tangent_solve_time, solve_elapsed)
        push!(tangent_status, string(st))
        ok = st in (MOI.OPTIMAL, MOI.ALMOST_OPTIMAL, MOI.SLOW_PROGRESS) &&
             has_values(model)
        if !ok
            push!(trial_pep_time, 0.0)
            verbose && @warn "SLM tangent failed" it st Δ
            Δ *= 0.5
            push!(Δ_hist, Δ); push!(ρ_hist, NaN); push!(acc_hist, false)
            push!(ω_hist, copy(ω)); push!(values, W)
            push!(solves_hist, npep); push!(tangent_hist, ntan)
            push!(time_hist, time() - t0)
            Δ < Δmin && break
            continue
        end
        step = value.(dω)
        pred = objective_value(model)
        ωt = ω .+ step
        t_trial_pep = time()
        Wt, solt = _safe_pep(dp, ωt; require_certified)
        push!(trial_pep_time, time() - t_trial_pep)
        npep += 1

        if abs(Wt - W) <= tolW && norm(step) < tolstep
            if Wt < W && solt !== nothing
                ω, W, sol = ωt, Wt, solt
            end
            push!(Δ_hist, Δ); push!(ρ_hist, NaN); push!(acc_hist, true)
            push!(ω_hist, copy(ω)); push!(values, W)
            push!(solves_hist, npep); push!(tangent_hist, ntan)
            push!(time_hist, time() - t0)
            verbose && @info "SLM converged" it W
            break
        end

        ρ = pred < -1e-15 ? (Wt - W) / pred : (Wt < W ? 1.0 : -Inf)
        accept = solt !== nothing && ρ > ρ_bad
        if accept
            if hessian == :bfgs
                gt = gradω(ωt, solt)
                B_init = _damped_bfgs!(B, step, gt .- g, B_init)
                g = gt
            end
            ω, W, sol = ωt, Wt, solt
            ρ >= ρ_good && (Δ *= 2.0)
        else
            Δ *= 0.5
        end
        push!(Δ_hist, Δ); push!(ρ_hist, ρ); push!(acc_hist, accept)
        push!(ω_hist, copy(ω)); push!(values, W)
        push!(solves_hist, npep); push!(tangent_hist, ntan)
        push!(time_hist, time() - t0)
        verbose && @info "SLM iter $it" W pred ΔW = Wt - values[end - 1] ρ Δ accept
        Δ < Δmin && break
    end
    if stats !== nothing
        stats[:Δ] = Δ_hist
        stats[:ρ] = ρ_hist
        stats[:accepted] = acc_hist
        stats[:initial_pep_time] = initial_pep_time
        stats[:tangent_build_time] = tangent_build_time
        stats[:tangent_solve_time] = tangent_solve_time
        stats[:trial_pep_time] = trial_pep_time
        stats[:tangent_status] = tangent_status
    end
    return DesignTrace(ω_hist, values, solves_hist, npep, tangent_hist, time_hist)
end
